// The mech plating textures, generated by Mining Mike's boss kit plating() run verbatim in a browser canvas.
//
//   NODE_PATH=$(npm root -g) node tools/textures/gen_mech_plating.mjs
//
// Writes assets/textures/mech/<name>.png (base colour), <name>_orm.png (occlusion, roughness, metal) and <name>_n.png (a tangent space normal map
// derived from the kit's bump canvas, because glTF has normal maps and no bump maps).
//
// Provenance: RubenTipparach/godot-sandbox godot-sandbox/docs/mockups/tank_bosses_kit.js at 3336b88,
// functions mkCanvas, toTex, plating and textures, copied unchanged except two lines: toTex returns the
// canvas instead of a THREE texture, and the glow and pillar sprites stay canvases. Owner, 2026-10-24:
// "The mech boss and Uber mech stuff are some of the best in mining mike". A documented exception to
// "textures are Material Maker graphs" (CLAUDE.md section 13).
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";
const { chromium } = createRequire(import.meta.url)("playwright");

const OUT = path.resolve("assets/textures/mech");
const KIT = path.resolve("tools/textures/mech_plating_kit.js");

fs.mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const page = await browser.newPage();
await page.setContent("<!doctype html><body></body>");
await page.addScriptTag({ path: KIT });
const out = await page.evaluate(() => window.__out);
for (const [name, url] of Object.entries(out)) {
  fs.writeFileSync(path.join(OUT, name + ".png"), Buffer.from(url.split(",")[1], "base64"));
  console.log("wrote", name);
}
// the decal sheet's table, for the Blender kit (mech_kit.Kit.decal): name -> [col, row, cols, rows] on an 8 by 8 grid
fs.writeFileSync(path.join(OUT, "decals.json"), JSON.stringify({ grid: 8, cells: await page.evaluate(() => window.__decals) }, null, 1) + "\n");
console.log("wrote decals.json");
await browser.close();
